Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
#define endl '\n'
using namespace std;

const int N = 10;
const int MAXV = 203;
const int INF = 1000000000;

string mp[N];
int n_experts[N][N] = {};
int n_help[N][N] = {};
int infected_at[N][N] = {};
int tim[10][10][10][10];

int dir_i[] = {-1, 1, 0, 0};
int dir_j[] = {0, 0, -1, 1};

struct Edge {
    int to, rev, cap;
};
vector<Edge> flow_graph[MAXV];

void add_flow_edge(int u, int v, int c) {
    flow_graph[u].push_back({v, (int)flow_graph[v].size(), c});
    flow_graph[v].push_back({u, (int)flow_graph[u].size() - 1, 0});
}

int edmonds_karp(int s, int t) {
    int total = 0;
    while (true) {
        int parent[MAXV], parent_edge[MAXV];
        memset(parent, -1, sizeof parent);
        parent[s] = s;
        queue<int> q;
        q.push(s);
        while (!q.empty() && parent[t] == -1) {
            int u = q.front(); q.pop();
            for (int i = 0; i < (int)flow_graph[u].size(); ++i) {
                const Edge &e = flow_graph[u][i];
                if (e.cap > 0 && parent[e.to] == -1) {
                    parent[e.to] = u;
                    parent_edge[e.to] = i;
                    q.push(e.to);
                }
            }
        }
        if (parent[t] == -1) break;
        int push = INF;
        for (int v = t; v != s; v = parent[v]) {
            push = min(push, flow_graph[parent[v]][parent_edge[v]].cap);
        }
        for (int v = t; v != s; v = parent[v]) {
            Edge &e = flow_graph[parent[v]][parent_edge[v]];
            e.cap -= push;
            flow_graph[v][e.rev].cap += push;
        }
        total += push;
    }
    return total;
}

int node_no(int n, int i, int j, bool right) {
    return i * n + j + (right ? n * n : 0);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n, t;
    cin >> n >> t;
    string line;
    pair<int,int> blast;

    for (int i = 0; i < n; ++i) {
        cin >> line;
        for (int j = 0; j < n; ++j) {
            char ch = line[j];
            if (ch == 'Y') mp[i][j] = 'Y';
            else if (ch == 'Z') {
                mp[i][j] = 'Z';
                blast = {i, j};
            } else {
                mp[i][j] = '.';
                n_experts[i][j] += ch - '0';
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        cin >> line;
        for (int j = 0; j < n; ++j) {
            if (line[j] != 'Y' && line[j] != 'Z') n_help[i][j] += line[j] - '0';
        }
    }

    memset(infected_at, -1, sizeof infected_at);
    infected_at[blast.first][blast.second] = 0;
    queue<pair<int,int>> q;
    q.push(blast);
    while (!q.empty()) {
        int i = q.front().first, j = q.front().second;
        q.pop();
        for (int d = 0; d < 4; ++d) {
            int ni = i + dir_i[d], nj = j + dir_j[d];
            if (0 <= ni && ni < n && 0 <= nj && nj < n && mp[ni][nj] == '.' && infected_at[ni][nj] == -1) {
                infected_at[ni][nj] = infected_at[i][j] + 1;
                q.push({ni, nj});
            }
        }
    }

    memset(tim, -1, sizeof tim);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (mp[i][j] != '.') continue;
            tim[i][j][i][j] = 0;
            queue<pair<int,int>> qq;
            qq.push({i, j});
            while (!qq.empty()) {
                int ii = qq.front().first, jj = qq.front().second;
                qq.pop();
                if (infected_at[ii][jj] == -1 || tim[i][j][ii][jj] < infected_at[ii][jj]) {
                    for (int d = 0; d < 4; ++d) {
                        int ni = ii + dir_i[d], nj = jj + dir_j[d];
                        if (0 <= ni && ni < n && 0 <= nj && nj < n && mp[ni][nj] == '.'
                            && (infected_at[ni][nj] == -1 || tim[i][j][ii][jj] + 1 <= infected_at[ni][nj])
                            && tim[i][j][ni][nj] == -1) {
                            tim[i][j][ni][nj] = tim[i][j][ii][jj] + 1;
                            qq.push({ni, nj});
                        }
                    }
                }
            }
        }
    }

    int src = 2 * n * n;
    int sink = src + 1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (n_experts[i][j]) add_flow_edge(src, node_no(n, i, j, false), n_experts[i][j]);
            if (n_help[i][j]) add_flow_edge(node_no(n, i, j, true), sink, n_help[i][j]);
            for (int ii = 0; ii < n; ++ii) {
                for (int jj = 0; jj < n; ++jj) {
                    if (0 <= tim[i][j][ii][jj] && tim[i][j][ii][jj] <= t) {
                        add_flow_edge(node_no(n, i, j, false), node_no(n, ii, jj, true), INF);
                    }
                }
            }
        }
    }

    cout << edmonds_karp(src, sink) << endl;
    return 0;
}
